@Override
public void render(PoseStack poseStack, MultiBufferSource bufferSource, int packedLight, Player player, float limbAngle, float limbSwingAmount, float partialTick, float ageInTicks, float headYaw, float headPitch) {
	ItemStack stack = player.getMainHandItem();
	Color color = ArcanusHelper.getMagicColor(player);

	model.showMagicCircles(ArcanusComponents.getPattern(player));

	poseStack.pushPose();
	poseStack.translate(0, 0.65, -0.35);

	model.setupAnim(player, limbAngle, limbSwingAmount, ageInTicks, headYaw, headPitch);
	model.showMagicCircles(ArcanusComponents.getPattern(player));

	if(ArcanusComponents.isCasting(player) && stack.getItem() instanceof StaffItem) {
		poseStack.translate(player.getMainArm() == HumanoidArm.RIGHT ? -0.35 : 0.35, 0, 0.05);
		poseStack.mulPose(Axis.YP.rotationDegrees(player.getMainArm() == HumanoidArm.RIGHT ? 65 : -65));
	}

	poseStack.pushPose();
	poseStack.translate(0, 0, Mth.sin((player.tickCount + player.getId() + partialTick) / (Mth.PI * 2)) * 0.05f);
	model.first.render(poseStack, bufferSource.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color.asIntARGB());
	poseStack.popPose();

	poseStack.pushPose();
	poseStack.translate(0, 0, Mth.cos((player.tickCount + player.getId() + partialTick) / (Mth.PI * 2)) * 0.05f);
	model.second.render(poseStack, bufferSource.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color.asIntARGB());
	poseStack.popPose();

	poseStack.pushPose();
	poseStack.translate(0, 0, Mth.sin((player.tickCount + player.getId() + partialTick) / (Mth.PI * 2)) * 0.05f);
	model.third.render(poseStack, bufferSource.getBuffer(ArcanusClient.getMagicCircles(TEXTURE)), LightTexture.FULL_BRIGHT, OverlayTexture.NO_OVERLAY, color.asIntARGB());
	poseStack.popPose();

	poseStack.popPose();
}

public static void renderSpellCircle(float alive, float scale, float horizontalScale, float xDir, float yDir, float zDir, int color, PoseStack ms, MultiBufferSource buffers) {
	ms.pushPose();
	double ratio = 0.0625 * horizontalScale;

	Vec3 direction = new Vec3(xDir, yDir, zDir);
	Vec3 normal = new Vec3(0f, 0f, 1f);
	Vec3 axis = normal.cross(direction);
	double dot = normal.dot(direction);

	// Very small threshold to see if it's parallel or not.
	if(axis.length() < 1e-6) {
		// If it's parallel but the dot product is negative we flip it.
		if(dot < 0) {
			ms.mulPose(Axis.XP.rotationDegrees(180f));
		}
	} else {
		float angle = (float) Math.acos(dot);
		ms.mulPose(new Quaternionf().fromAxisAngleRad((float) axis.x, (float) axis.y, (float) axis.z, angle));
	}

	ms.translate(0, 0, 0.1);
	ms.scale((float) ratio * scale, (float) ratio * scale, (float) ratio);

	int r = PsiRenderHelper.r(color);
	int g = PsiRenderHelper.g(color);
	int b = PsiRenderHelper.b(color);

	for(int i = 0; i < LAYERS.length; i++) {
		int rValue = r;
		int gValue = g;
		int bValue = b;

		if(i == 1) {
			rValue = gValue = bValue = 0xFF;
		} else if(i == 2) {
			int minBrightness = (int) (1 / (1 - BRIGHTNESS_FACTOR));
			if(rValue == 0 && gValue == 0 && bValue == 0) {
				rValue = gValue = bValue = minBrightness;
			}
			if(rValue > 0 && rValue < minBrightness) {
				rValue = minBrightness;
			}
			if(gValue > 0 && gValue < minBrightness) {
				gValue = minBrightness;
			}
			if(bValue > 0 && bValue < minBrightness) {
				bValue = minBrightness;
			}

			rValue = (int) Math.min(rValue / BRIGHTNESS_FACTOR, 0xFF);
			gValue = (int) Math.min(gValue / BRIGHTNESS_FACTOR, 0xFF);
			bValue = (int) Math.min(bValue / BRIGHTNESS_FACTOR, 0xFF);
		}

		ms.pushPose();
		ms.mulPose(Axis.ZP.rotationDegrees(i == 0 ? -alive : alive));

		VertexConsumer buffer = buffers.getBuffer(LAYERS[i]);
		Matrix4f mat = ms.last().pose();
		int fullbright = 0xF000F0;
		addVertex(buffer, mat, -32, 32, rValue, gValue, bValue, 0, 1, fullbright);
		addVertex(buffer, mat, 32, 32, rValue, gValue, bValue, 1, 1, fullbright);
		addVertex(buffer, mat, 32, -32, rValue, gValue, bValue, 1, 0, fullbright);
		addVertex(buffer, mat, -32, -32, rValue, gValue, bValue, 0, 0, fullbright);
		ms.popPose();

		ms.translate(0, 0, -0.5);
	}

	ms.popPose();
}

protected SpellParticle(ClientWorld world, double x, double y, double z,
                        double velocityX, double velocityY, double velocityZ,
                        SpriteProvider spriteProvider,
                        SpellEngineParticles.Entry entry,
                        ParticleGroup.Appearance config,
                        @Nullable Entity sourceEntity) {
    super(world, x, y, z);
    this.spriteProvider = spriteProvider;
    this.frameCount = entry.texture().frames();
    this.pivot = entry.pivot();

    this.facing = config.facing != null ? config.facing : ParticleGroup.Facing.CAMERA;
    this.render = config.render != null ? config.render : ParticleGroup.Render.TRANSLUCENT;
    this.glow = config.glow != null ? config.glow : true;
    var motion = config.motion != null ? config.motion : ParticleGroup.Motion.STATIC;
    this.motion = motion;

    // MARK: Motion preset (constants ported from V1 SpellUniversalParticle)

    this.collidesWithWorld = config.collides;
    switch (motion) {
        case STATIC -> {
            this.velocityX = velocityX;
            this.velocityY = velocityY;
            this.velocityZ = velocityZ;
            this.velocityMultiplier = 1F;
            this.gravityStrength = 0F;
        }
        case FLOAT, DECELERATE -> {
            this.velocityMultiplier = motion == ParticleGroup.Motion.DECELERATE ? 0.768F : 0.96F;
            this.gravityStrength = 0F;
            this.velocityX = velocityX + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityY = velocityY + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityZ = velocityZ + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.x += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.y += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.z += (this.random.nextFloat() - this.random.nextFloat()) * 0.05F;
            this.setPos(this.x, this.y, this.z);
        }
        case ASCEND -> {
            this.velocityMultiplier = 0.96F;
            this.gravityStrength = -0.1F;
            this.ascending = true;
            this.velocityX = velocityX * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                    + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
            this.velocityY = velocityY * 0.2F + 0.02F;
            this.velocityZ = velocityZ * (velocityX == 0 && velocityZ == 0 ? 0.1F : 1F)
                    + (this.random.nextFloat() - this.random.nextFloat()) * 0.005F;
        }
        case BURST -> {
            this.velocityMultiplier = 0.7F;
            this.gravityStrength = 0.5F;
            this.velocityX = velocityX * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
            this.velocityY = velocityY * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
            this.velocityZ = velocityZ * 0.4F + (this.random.nextFloat() - this.random.nextFloat()) * 0.02F;
        }
        case DRIFT -> {
            // Vanilla SnowflakeParticle's motion: a wide random scatter, gravity,
            // and per-axis damping that bleeds vertical speed faster than lateral,
            // so particles fan out as they settle rather than dropping in a line.
            this.velocityMultiplier = 1F;
            this.gravityStrength = 0.225F;
            this.velocityX = velocityX + (Math.random() * 2.0 - 1.0) * 0.05F;
            this.velocityY = velocityY + (Math.random() * 2.0 - 1.0) * 0.05F;
            this.velocityZ = velocityZ + (Math.random() * 2.0 - 1.0) * 0.05F;
        }
    }
    if (config.gravity != null) {
        this.gravityStrength = config.gravity;
    }
    if (config.drag != null) {
        this.velocityMultiplier = config.drag;
    }

    // MARK: Lifetime & playback

    float playbackSpeed = config.playback_speed == 0F ? 1F : config.playback_speed;
    this.reversedPlayback = playbackSpeed < 0F;
    float lifetimeRoll = 1F + (this.random.nextFloat() * 2F - 1F) * MathHelper.clamp(config.lifetime_variance, 0F, 1F);
    this.maxAge = Math.max(1, Math.round(
            entry.lifetime() * motion.lifetime_factor * lifetimeRoll / Math.abs(playbackSpeed)));

    // MARK: Appearance

    float darken = 1F - this.random.nextFloat() * MathHelper.clamp(config.color_variance, 0F, 1F);
    float colorAlpha = 1F;
    if (config.color >= 0) {
        var color = Color.fromRGBA(config.color);
        this.setColor(color.red() * darken, color.green() * darken, color.blue() * darken);
        colorAlpha = color.alpha();
    } else {
        this.setColor(darken, darken, darken);
    }
    this.baseOpacity = config.opacity * colorAlpha;
    this.opacityCurve = config.opacity_curve;
    this.alpha = baseOpacity * (opacityCurve != null ? opacityCurve.sample(0F) : 1F);

    float scaleVariance = MathHelper.clamp(config.scale_variance, 0F, 1F);
    this.spawnScale = config.scale * (1F + (this.random.nextFloat() * 2F - 1F) * scaleVariance);
    this.scale = spawnScale;
    this.scaleEasing = config.scale_easing;
    this.scaleMultiplier = config.scale_multiplier;

    // MARK: Attachment

    this.attachment = config.attachment;
    this.followEntity = attachment != ParticleGroup.Attachment.NONE ? sourceEntity : null;
    if (followEntity != null) {
        this.followDiff = new Vec3d(this.x - followEntity.getX(), this.y - followEntity.getY(), this.z - followEntity.getZ());
    }
    // Seed the ground cache with the spawn height (a GROUND-anchored batch already
    // resolves to the floor), so the first frame is correct before any re-probe.
    this.groundY = this.y;

    updateSprite();
    updateSkipRender();
}
